121	
122	        size_t src_offset_prev = 0;
123	        size_t processed_size = 0;
124	
125	        const auto& decoder = (alphabet == "bitcoin") ? Base58::bitcoin() :
126	                             ((alphabet == "flickr") ? Base58::flickr() :
127	                             ((alphabet == "ripple") ? Base58::ripple() :
128	                                                       Base58::base58()));
129	
130	        std::string decoded;
131	        for (size_t row = 0; row < input_rows_count; ++row)
132	        {
133	            size_t srclen = src_offsets[row] - src_offset_prev - 1;
