149	                {
150	                    throw Exception(e.what(), ErrorCodes::BAD_ARGUMENTS);
151	                }
152	            size_t outlen = decoded.size();
153	
154	            if (processed_size + outlen >= current_allocated_size)
155	            {
156	                current_allocated_size += current_allocated_size;
157	                dst_data.resize(current_allocated_size);
158	                auto processed_offset = dst_pos - dst;
159	                dst = dst_data.data();
160	                dst_pos = dst;
161	                dst_pos += processed_offset;
162	            }
163	            std::memcpy(dst_pos, decoded.c_str(), ++outlen);
164	
