56	template <typename Func>
57	class FunctionBase64Conversion : public IFunction
58	{
59	public:
60	    static constexpr auto name = Func::name;
61	
62	    static FunctionPtr create(ContextPtr)
63	    {
64	        return std::make_shared<FunctionBase64Conversion>();
65	    }
66	
67	    String getName() const override
68	    {
69	        return Func::name;
70	    }
71	
72	    size_t getNumberOfArguments() const override
73	    {
74	        return 1;
75	    }
76	
77	    bool isSuitableForShortCircuitArgumentsExecution(const DataTypesWithConstInfo & /*arguments*/) const override { return true; }
78	
79	    bool useDefaultImplementationForConstants() const override
80	    {
81	        return true;
82	    }
83	
84	    DataTypePtr getReturnTypeImpl(const ColumnsWithTypeAndName & arguments) const override
85	    {
86	        if (!WhichDataType(arguments[0].type).isString())
87	            throw Exception(
88	                "Illegal type " + arguments[0].type->getName() + " of 1st argument of function " + getName() + ". Must be String.",
89	                ErrorCodes::ILLEGAL_TYPE_OF_ARGUMENT);
90	
91	        return std::make_shared<DataTypeString>();
92	    }
93	
94	    ColumnPtr executeImpl(const ColumnsWithTypeAndName & arguments, const DataTypePtr &, size_t input_rows_count) const override
95	    {
96	        const ColumnPtr column_string = arguments[0].column;
97	        const ColumnString * input = checkAndGetColumn<ColumnString>(column_string.get());
98	
99	        if (!input)
100	            throw Exception(
101	                "Illegal column " + arguments[0].column->getName() + " of first argument of function " + getName() + ", must be of type String",
102	                ErrorCodes::ILLEGAL_COLUMN);
103	
104	        auto dst_column = ColumnString::create();
105	        auto & dst_data = dst_column->getChars();
106	        auto & dst_offsets = dst_column->getOffsets();
107	
108	        size_t reserve = Func::getBufferSize(input->getChars().size(), input->size());
109	        dst_data.resize(reserve);
110	        dst_offsets.resize(input_rows_count);
111	
112	        const ColumnString::Offsets & src_offsets = input->getOffsets();
113	
114	        const auto * source = input->getChars().data();
115	        auto * dst = dst_data.data();
116	        auto * dst_pos = dst;
117	
118	        size_t src_offset_prev = 0;
119	
120	        for (size_t row = 0; row < input_rows_count; ++row)
121	        {
122	            size_t srclen = src_offsets[row] - src_offset_prev - 1;
123	            size_t outlen = 0;
124	
125	            if constexpr (std::is_same_v<Func, Base64Encode>)
126	            {
127	                /*
128	                 * Some bug in sse arm64 implementation?
129	                 * `base64Encode(repeat('a', 46))` returns wrong padding character
130	                 */
131	#if defined(__aarch64__)
132	                    outlen = tb64senc(reinterpret_cast<const uint8_t *>(source), srclen, reinterpret_cast<uint8_t *>(dst_pos));
133	#else
134	                    outlen = _tb64e(reinterpret_cast<const uint8_t *>(source), srclen, reinterpret_cast<uint8_t *>(dst_pos));
135	#endif
136	            }
137	            else if constexpr (std::is_same_v<Func, Base64Decode>)
138	            {
139	                if (srclen > 0)
140	                {
141	#if defined(__aarch64__)
142	                   outlen = tb64sdec(reinterpret_cast<const uint8_t *>(source), srclen, reinterpret_cast<uint8_t *>(dst_pos));
143	#else
144	                   outlen = _tb64d(reinterpret_cast<const uint8_t *>(source), srclen, reinterpret_cast<uint8_t *>(dst_pos));
145	#endif
146	
147	                    if (!outlen)
148	                        throw Exception("Failed to " + getName() + " input '" + String(reinterpret_cast<const char *>(source), srclen) + "'", ErrorCodes::INCORRECT_DATA);
149	                }
150	            }
151	            else
152	            {
153	                if (srclen > 0)
154	                {
155	                    // during decoding character array can be partially polluted
156	                    // if fail, revert back and clean
157	                    auto * savepoint = dst_pos;
158	                    outlen = _tb64d(reinterpret_cast<const uint8_t *>(source), srclen, reinterpret_cast<uint8_t *>(dst_pos));
159	                    if (!outlen)
160	                    {
161	                        outlen = 0;
162	                        dst_pos = savepoint; //-V1048
163	                        // clean the symbol
164	                        dst_pos[0] = 0;
165	                    }
166	                }
167	            }
168	
169	            /// Base64 library is using AVX-512 with some shuffle operations.
170	            /// Memory sanitizer don't understand if there was uninitialized memory in SIMD register but it was not used in the result of shuffle.
171	            __msan_unpoison(dst_pos, outlen);
172	
173	            source += srclen + 1;
174	            dst_pos += outlen;
175	            *dst_pos = '\0';
176	            dst_pos += 1;
177	
178	            dst_offsets[row] = dst_pos - dst;
179	            src_offset_prev = src_offsets[row];
180	        }
181	
182	        dst_data.resize(dst_pos - dst);
183	
184	        return dst_column;
185	    }
186	};
